import {materials} from '../../core/index.js';import {FACE} from '../../modeling/parts.js';import {THREE,roundedRect,mesh,hole,solid,ring,box,cylinder} from './geometry.js';import {spec,vents} from './dimensions.js';
function frontShape(){const s=new THREE.Shape();s.moveTo(-8,-16);s.lineTo(-5.15,-16);s.lineTo(-5.15,-8.1);s.lineTo(5.15,-8.1);s.lineTo(5.15,-16);s.lineTo(8,-16);s.absarc(8,-12,4,-Math.PI/2,0,false);s.lineTo(12,12);s.absarc(8,12,4,0,Math.PI/2,false);s.lineTo(-8,16);s.absarc(-8,12,4,Math.PI/2,Math.PI,false);s.lineTo(-12,-12);s.absarc(-8,-12,4,Math.PI,Math.PI*1.5,false);s.closePath();for(const[x,y]of spec.mounting.centres)hole(s,x,y,2.5);for(const{x,y}of vents)s.holes.push(roundedRect(.8,1.65,.4,{cx:x,cy:y,path:new THREE.Path()}));return s;}
function sideShape(){const s=new THREE.Shape();s.moveTo(-8,16);s.absarc(-8,12,4,Math.PI/2,Math.PI,false);s.lineTo(-12,-12);s.absarc(-8,-12,4,Math.PI,Math.PI*1.5,false);s.lineTo(-5.15,-16);s.lineTo(-5.15,-14.9);s.lineTo(-8,-14.9);s.absarc(-8,-12,2.9,-Math.PI/2,-Math.PI,true);s.lineTo(-10.9,12);s.absarc(-8,12,2.9,Math.PI,Math.PI/2,true);s.lineTo(-8,16);s.closePath();return s;}
function relief(parent,mat){const frame=new THREE.Group();frame.position.set(0,-11,-3.9);frame.quaternion.copy(FACE.back);frame.name='Original ENV-II physical unpainted M5 moulding';parent.add(frame);const glyphs=[];for(const[name,points]of[['M',[[-4.6,-2],[-4.6,2],[-4.1,2],[-2.55,.3],[-1,2],[-.5,2],[-.5,-2],[-1,-2],[-1,1.2],[-2.55,-.45],[-4.1,1.2],[-4.1,-2]]],['5',[[.4,2],[4.5,2],[4.5,1.5],[.95,1.5],[.95,.35],[3.3,.35],[4.2,-.15],[4.5,-.7],[4.5,-1.4],[4.05,-2],[.4,-2],[.4,-1.5],[3.75,-1.5],[3.95,-1.15],[3.95,-.8],[3.7,-.35],[3.15,-.15],[.4,-.15]]]])glyphs.push(mesh(frame,solid(new THREE.Shape(points.map(p=>new THREE.Vector2(...p))),.1),mat,[0,0,0],'U001-B actual white '+name+' relief material'));return{frame,glyphs};}
export function casing(host){const frontMat=materials.plastic(0xf0f0e8,{roughness:.82}),rearMat=materials.plastic(0xe9ece4,{roughness:.83}),back=roundedRect(24,32,4);for(const[x,y]of spec.mounting.centres)hole(back,x,y,2.5);hole(back,0,-4,1.6);const rear=mesh(host.body,solid(back,1),rearMat,[0,0,-3.9],'ENV-II own closed rear skin;true bores/retainer opening'),front=mesh(host.body,solid(frontShape(),1),frontMat,[0,0,3],'ENV-II own closed front skin with40real staggered air passages and actual Grove boundary notch'),left=sideShape(),right=new THREE.Shape(left.getPoints(64).map(p=>new THREE.Vector2(-p.x,p.y))),rearSides=[],frontSides=[];for(const[s,name]of[[left,'left'],[right,'right']]){rearSides.push(mesh(host.body,solid(s,2.95),rearMat,[0,0,-2.9],'ENV-II own rear half '+name+' curved perimeter'));frontSides.push(mesh(host.body,solid(s,2.95),frontMat,[0,0,.05],'ENV-II own front half '+name+' curved perimeter'));}const rearTop=box(host.body,[16,1.1,2.95],[0,15.45,-1.425],rearMat,'ENV-II closed rear half top end'),frontTop=box(host.body,[16,1.1,2.95],[0,15.45,1.525],frontMat,'ENV-II closed front half top end'),lowerFloor=box(host.body,[10.3,1.1,1.5],[0,-15.45,-2.15],rearMat,'ENV-II actual lower white bridge supports receiving floor'),bosses=[];for(const[x,y]of spec.mounting.centres)for(const[z,mat]of[[-2.9,rearMat],[.05,frontMat]])bosses.push(mesh(host.body,ring(3.2,2.5,2.95),mat,[x,y,z],'ENV-II true open mounting sleeve,closed half material'));const screwBoss=mesh(host.body,ring(1.95,.85,5.9),rearMat,[0,-4,-2.9],'ENV-II fixed central screw support sleeve'),posts=[];for(const x of[-8,8])for(const y of[-11.5,12])posts.push(mesh(host.body,cylinder(.95,.7),rearMat,[x,y,-2.55],'ENV-II inferred physical rear-to-PCB support post'));return{front,rear,rearSides,frontSides,rearTop,frontTop,lowerFloor,bosses,screwBoss,posts,relief:relief(host.body,rearMat)};}
export function fixing(host){const metal=materials.metal(0xaeb3a7,{roughness:.45}),s=new THREE.Shape();s.absarc(0,0,1.4,0,Math.PI*2,false);const p=new THREE.Path();for(let i=0;i<6;i++){const a=i*Math.PI/3;i?p.lineTo(Math.cos(a)*.56,Math.sin(a)*.56):p.moveTo(Math.cos(a)*.56,Math.sin(a)*.56);}p.closePath();s.holes.push(p);const head=mesh(host.body,solid(s,.58),metal,[0,-4,-3.88],'ENV-II actual fixed screw head with inferred true hex recess'),floor=mesh(host.body,cylinder(.55,.08),materials.plastic(0x454b3f),[0,-4,-3.34],'ENV-II true recessed drive floor'),washer=mesh(host.body,ring(1.65,.7,.3),metal,[0,-4,-3.3],'ENV-II fixed rear screw bearing'),shank=mesh(host.body,cylinder(.7,5.7),metal,[0,-4,-.15],'ENV-II retained screw shaft;no dynamic joint');return{head,floor,washer,shank};}
